mapper.select:
select embedding.chunk_id, embedding.model, embedding.dimensions, embedding.vector_json
from knowledge_chunk_embeddings embedding
inner join knowledge_chunks chunk on chunk.id = embedding.chunk_id
inner join knowledge_documents document on document.id = chunk.document_id
where  and embedding.model = #{model}
order by embedding.chunk_id desc limit #{limit}

select chunk.id, chunk.document_id, chunk.chunk_index, chunk.content
from knowledge_chunks chunk
inner join knowledge_documents document on document.id = chunk.document_id
left join knowledge_chunk_embeddings embedding on embedding.chunk_id = chunk.id
    and embedding.model = #{model}
where  and document.id = #{documentId}
  and embedding.chunk_id is null
order by chunk.id asc limit #{limit}
